---@class PiecesCollector
local PiecesCollector = Class('PiecesCollector')

-- ========================================================


-- 挂载在 SwitchablePlayer 的 Human 和 Cat 两个节点上, 分别监听 碰撞检测它们的 callbacks


--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


---@type PiecesCollectionUtils
local PiecesCollectionUtils = import('Game.DreamSpace.PiecesCollection.PiecesCollectionUtils')


---@type DreamSpaceSounds
local DreamSpaceSounds = import('Game.DreamSpace.Tools.DreamSpaceSounds'):GetInstance()

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Transform = CS.UnityEngine.Transform
local RectTransform = CS.UnityEngine.RectTransform


local Collider = CS.UnityEngine.Collider


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour

-- ========================================================


--local piecesTag = "Pieces" 


-- ========================================================


function PiecesCollector:__init()
    self.controller = nil
    self.DeliverFunc = nil -- Action<EmotionalPieces>, 且默认只绑一个函数
end


function PiecesCollector:__delete()
    self.DeliverFunc = nil
end



function PiecesCollector:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end

function PiecesCollector:Start()
    KTool.SetActive(self.controller.gameObject, true)

    -- ==============================
    -- 绑定 OnTriggerEnter() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end
    end

    ---:
    local collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
    assert( not isNull(collider), "gameobj 必须携带碰撞体" )
end


function PiecesCollector:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


---@return void
---@param other_ UnityEngine.Collider
function PiecesCollector:OnTriggerEnter(other_)

    --print("OnTriggerEnter, " .. self.controller.name)
    if not KTool.ContainTag(other_, PiecesCollectionUtils.piecesTag) then
        return
    end

    local emotionalPieces = DreamSpaceLuaUtils.GetLuaScr(other_.gameObject, "Game.DreamSpace.PiecesCollection.EmotionalPiece" )
    if isNull(emotionalPieces) then 
        printError("情绪碎片 gameobject 上没有绑脚本 EmotionalPieces")
        return
    end 

    if not isNull( self.DeliverFunc ) and (emotionalPieces.isBeCollected == false) then 
        print("DeliverFunc: " .. self.controller.name)
        emotionalPieces.isBeCollected = true
        self.DeliverFunc(emotionalPieces)
        -- 播放 情绪碎片 收集 声音:
        DreamSpaceSounds.Play( DreamSpaceSounds.sfx.emotionalDebris )
    end
end


return PiecesCollector

